window.__vaultPreview("d36cf0669efb00b6",{"text":"/**\n * Applies new files in supabase/migrations/ to the Supabase project, in order.\n * Uses the Management API with SUPABASE_ACCESS_TOKEN, so no database password is needed.\n * Records each one in supabase_migrations.schema_migrations (the same table the Supabase CLI uses).\n * Run with: npm run db:migrate\n */\nimport { config } from \"dotenv\";\nimport { readFileSync, readdirSync } from \"node:fs\";\nimport { join } from \"node:path\";\n\nconfig({ path: \".env.local\", quiet: true });\n\nconst DIR = \"supabase/migrations\";\n\nfunction projectRef(): string {\n  const url = process.env.NEXT_PUBLIC_SUPABASE_URL ?? \"\";\n  const ref = url.match(/^https:\\/\\/([a-z0-9]+)\\.supabase\\.co/)?.[1];\n  if (!ref) throw new Error(\"NEXT_PUBLIC_SUPABASE_URL in .env.local is missing or not a supabase.co URL.\");\n  return ref;\n}\n\nasync function sql(ref: string, [redacted] query: string): Promise<Record<string, unknown>[]> {\n  const res = await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`, {\n    method: \"POST\",\n    headers: { Authorization: `Bearer ${token}`, \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ query }),\n  });\n  const text = await res.text();\n  if (!res.ok) throw new Error(`Supabase refused the SQL (${res.status}): ${text.slice(0, 500)}`);\n  return text ? JSON.parse(text) : [];\n}\n\nconst quote = (s: string) => `'${s.replace(/'/g, \"''\")}'`;\n\nasync function main() {\n  const [redacted]\n  if (!token) throw new Error(\"Add SUPABASE_ACCESS_TOKEN to .env.local (supabase.com/dashboard/account/tokens).\");\n  const ref = projectRef();\n\n  await sql(ref, token, `create schema if not exists supabase_migrations;\n    create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);`);\n  const applied = new Set((await sql(ref, token, \"select version from supabase_migrations.schema_migrations\")).map((r) => String(r.version)));\n\n  const files = readdirSync(DIR).filter((f) => f.endsWith(\".sql\")).sort();\n  let count = 0;\n  for (const file of files) {\n    const [version, ...rest] = file.replace(/\\.sql$/, \"\").split(\"_\");\n    if (applied.has(version)) continue;\n    const body = readFileSync(join(DIR, file), \"utf8\");\n    await sql(ref, token, body);\n    await sql(ref, token, `insert into supabase_migrations.schema_migrations (version, name, statements)\n      values (${quote(version)}, ${quote(rest.join(\"_\"))}, array[${quote(body)}])`);\n    console.log(`applied ${file}`);\n    count++;\n  }\n  if (!count) console.log(\"up to date\");\n}\n\nmain().catch((e: unknown) => {\n  console.error(e instanceof Error ? e.message : e);\n  process.exit(1);\n});\n"});
